/* From Uiverse.io by Muaz-Aldalil - Tags: switch, radio-buttons, toggle switch */
.__UIV_SCOPE__ .toggle-checkbox {
  -webkit-appearance: none;
  -moz-appearance: none;
  appearance: none;
  display: none;
}

.__UIV_SCOPE__ .toggle-switch {
  background-color: gray;
  width: 78px;
  height: 32px;
  border-radius: 16px;
  position: relative;
  transition: 0.3s;
  cursor: pointer;
}

.__UIV_SCOPE__ .toggle-switch::before {
  content: "";
  font-weight: 900;
  background-color: white;
  width: 24px;
  height: 24px;
  position: absolute;
  border-radius: 50%;
  top: 4px;
  left: 4px;
  display: flex;
  justify-content: center;
  align-items: center;
  color: #ddd;
  transition: 0.3s;
}

.__UIV_SCOPE__ .toggle-checkbox:checked+.toggle-switch {
  background-color: #0075ff;
}

.__UIV_SCOPE__ .toggle-checkbox:checked+.toggle-switch::before {
  content: "";
  left: 50px;
  color: #0075ff;
}
